const crypto = require('crypto');
// Chữ ký TikTok Shop API 202309 (cần đối chiếu khi có app thật, xem contracts/internal/tiktok_api.md)
function tiktokSign(path, query, bodyStr, secret) {
  const keys = Object.keys(query).filter((k) => k !== 'sign' && k !== 'access_token').sort();
  let s = path + keys.map((k) => k + query[k]).join('');
  if (bodyStr) s += bodyStr;
  return crypto.createHmac('sha256', secret).update(secret + s + secret).digest('hex');
}
// Node Code của n8n không có URLSearchParams: tự ghép query
const toQuery = (q) => Object.keys(q).map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(q[k])).join('&');
const appKey = $env.TIKTOK_APP_KEY || '';
const appSecret = $env.TIKTOK_APP_SECRET || '';
if (!appKey || !appSecret) throw new Error('Thiếu TIKTOK_APP_KEY hoặc TIKTOK_APP_SECRET trong .env');
const API_BASE = ($env.TIKTOK_API_BASE || 'https://open-api.tiktokglobalshop.com').replace(/\/$/, '');
const AUTH_BASE = ($env.TIKTOK_AUTH_BASE || 'https://auth.tiktok-shops.com').replace(/\/$/, '');
const parse = (raw) => { try { return typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return { code: -1, message: String(raw).slice(0, 300) }; } };
// Hạn token TikTok trả về là thời điểm (Unix giây); phòng khi là số giây còn lại thì đổi ra thời điểm
const toEpoch = (v) => (Number(v) < 1e9 ? Math.floor(Date.now() / 1000) + Number(v) : Number(v));

const q = $input.first().json.query || {};
try {
  if ($env.TIKTOK_OAUTH_STATE && q.state !== $env.TIKTOK_OAUTH_STATE) throw new Error('state không khớp (link ủy quyền lạ)');
  if (!q.code) throw new Error('thiếu code trong link chuyển về');

  const t = parse(await this.helpers.httpRequest({
    method: 'GET', url: AUTH_BASE + '/api/v2/token/get', json: false, timeout: 20000,
    qs: { app_key: appKey, app_secret: appSecret, auth_code: q.code, grant_type: 'authorized_code' },
  }));
  if (t.code !== 0 || !t.data || !t.data.access_token) throw new Error(`đổi code lấy token lỗi: ${t.code} ${t.message}`);
  const d = t.data;

  const path = '/authorization/202309/shops';
  const query = { app_key: appKey, timestamp: Math.floor(Date.now() / 1000) };
  query.sign = tiktokSign(path, query, '', appSecret);
  const s = parse(await this.helpers.httpRequest({
    method: 'GET', url: API_BASE + path + '?' + toQuery(query), json: false, timeout: 20000,
    headers: { 'x-tts-access-token': d.access_token, 'content-type': 'application/json' },
  }));
  const shop = s.code === 0 && s.data && (s.data.shops || [])[0];
  if (!shop) throw new Error(`lấy danh sách shop lỗi: ${s.code} ${s.message}`);

  return [{ json: { ok: true, shop_id: String(shop.id), shop_cipher: shop.cipher, shop_name: shop.name || d.seller_name || null,
    region: shop.region || d.seller_base_region || null, access_token: d.access_token,
    access_expires: toEpoch(d.access_token_expire_in), refresh_token: d.refresh_token,
    refresh_expires: toEpoch(d.refresh_token_expire_in), scopes: d.granted_scopes || [] } }];
} catch (e) {
  return [{ json: { ok: false, error: e.message } }];
}

// Quyết định: làm mới token, xóa token (shop hủy ủy quyền), hay bỏ qua
const fromRouter = $('Router gọi tới').isExecuted;
const ev = fromRouter ? $('Router gọi tới').first().json : {};
const tok = $input.first().json;
if (ev.event_type === 'SELLER_DEAUTHORIZATION') return [{ json: { action: 'deauth', shop_id: ev.shop_id || tok.shop_id || '' } }];
if (!tok.access_token) return [{ json: { action: 'skip', reason: 'chưa có token (chủ shop chưa ủy quyền)' } }];
const hoursLeft = (new Date(tok.access_token_expires_at).getTime() - Date.now()) / 3600e3;
if (fromRouter || hoursLeft < 48) return [{ json: { action: 'refresh', ...tok, hours_left: Math.round(hoursLeft) } }];
return [{ json: { action: 'skip', reason: `token còn ${Math.round(hoursLeft)} giờ`, shop_id: tok.shop_id } }];

